static int fail, count;
#define EXPECT(name, want, got) do { uint64_t w=(want), g=(got); count++; printf("%s expected %llu → got %llu %s\n", name, (unsigned long long)w, (unsigned long long)g, w==g?"✓":"✗"); fail += w != g; } while (0)
typedef struct { uint8_t *p; size_t n; } chain;
static chain chain_new(void) { chain c={0}; if (posix_memalign((void **)&c.p,getpagesize(),65536)) abort(); memset(c.p,0,65536); mtl_pool_add(c.p,65536); return c; }
static void emit(chain *c, unsigned op, const void *a, size_t n) { size_t z=(8+n+7)&~7ull; op_hdr h={op,(uint32_t)z}; memcpy(c->p+c->n,&h,8); if(n) memcpy(c->p+c->n+8,a,n); c->n+=z; }
static tex_t tex(unsigned w) { static uint64_t s=9000; tex_t t={.serial=s++}; t.d.width=t.d.height=w; t.d.depth=t.d.samples=1; t.d.levels=2; t.d.target=NVN_TEXTURE_TARGET_2D; t.d.format=NVN_FORMAT_RGBA8; return t; }
static int view(const tex_t *t, int lv) { static int id=1200; view_t v={.set_levels=1,.base_level=lv,.nlevels=1}; mtl_reg_tex(id,t,&v); return id++; }
static void set_rt(chain *c, const tex_t *a, const tex_t *b, int alv) { p_set_rt r={.n=b?2:1}; r.color[0]=a; r.color[1]=b; for(int i=0;i<r.n;i++){r.has_cview[i]=1;r.cview[i].set_levels=1;r.cview[i].base_level=i?0:alv;r.cview[i].nlevels=1;} emit(c,OP_SET_RT,&r,sizeof r); p_viewports v={.n=1};v.v[0][2]=v.v[0][3]=8;emit(c,OP_VIEWPORTS,&v,sizeof v);p_scissor sc={0,0,8,8};emit(c,OP_SCISSOR,&sc,sizeof sc); }
static void clear_color(chain *c, int i, float r, float g, float b) { p_clear_color x={.index=i,.mask=15,.rgba={r,g,b,1}}; emit(c,OP_CLEAR_COLOR,&x,sizeof x); }
static void bind_prog(chain *c, prog_t *p) { p_bind_program b={p,3}; emit(c,OP_BIND_PROGRAM,&b,sizeof b); }
static void bind_tex(chain *c, int id) { p_bind_handles b={.stage=1,.first=0,.n=1};b.h[0]=id;emit(c,OP_BIND_TEX,&b,sizeof b); }
static void draw_cmd(chain *c) { p_draw d={NVN_DRAW_PRIMITIVE_TRIANGLES,0,3}; emit(c,OP_DRAW,&d,sizeof d); }
static void blend(chain *c) { color_st col={1,NVN_LOGIC_OP_COPY,NVN_ALPHA_FUNC_ALWAYS}; p_bind_state x={.kind=1};memcpy(x.bytes,&col,sizeof col);emit(c,OP_BIND_STATE,&x,sizeof x); blend_st b={0,NVN_BLEND_FUNC_SRC_ALPHA,NVN_BLEND_FUNC_ONE_MINUS_SRC_ALPHA,NVN_BLEND_FUNC_ONE,NVN_BLEND_FUNC_ZERO,NVN_BLEND_EQUATION_ADD,NVN_BLEND_EQUATION_ADD};x.kind=0;memcpy(x.bytes,&b,sizeof b);emit(c,OP_BIND_STATE,&x,sizeof x); }
static void ds_off(chain *c) { ds_st d={0,0,NVN_DEPTH_FUNC_ALWAYS,0,NVN_STENCIL_FUNC_ALWAYS,NVN_STENCIL_FUNC_ALWAYS,NVN_STENCIL_OP_KEEP,NVN_STENCIL_OP_KEEP,NVN_STENCIL_OP_KEEP,NVN_STENCIL_OP_KEEP,NVN_STENCIL_OP_KEEP,NVN_STENCIL_OP_KEEP}; p_bind_state x={.kind=5}; memcpy(x.bytes,&d,sizeof d); emit(c,OP_BIND_STATE,&x,sizeof x); }
static void readback(const tex_t *t, uint8_t out[256]) { id<MTLBuffer> b=[g_dev newBufferWithLength:256 options:MTLResourceStorageModeShared]; [blit() copyFromTexture:tex_mtl(t) sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(8,8,1) toBuffer:b destinationOffset:0 destinationBytesPerRow:32 destinationBytesPerImage:256]; uint64_t f=mtl_sub_commit(); EXPECT("submit completed",1,mtl_wait(f,5000000000ull)); EXPECT("no error in submit feedback",0,mtl_last_commit_error()); memcpy(out,b.contents,256); }
static NvProg *g_tkeep[256]; static int g_tnkeep;   /* Program objects in the tests are permanent: after a free, a new object may land at the same address, and the pipeline cache, keyed by object address, would return the old pipeline (in production program objects are never freed) */
static void setup_prog(prog_t *pg) { NSError *e=nil; id<MTLLibrary> l=[g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal; vertex float4 v(uint n[[vertex_id]]){float2 p[3]={float2(-1,-1),float2(3,-1),float2(-1,3)};return float4(p[n],0,1);}\nfragment float4 red(){return float4(1,0,0,0.5);}\nstruct A{texture2d<float> t[[id(0)]];}; fragment float4 sample(constant A&a[[buffer(0)]]){return a.t.read(uint2(0));}\n" options:nil error:&e]; if(!l){fprintf(stderr,"%s\n",e.localizedDescription.UTF8String);abort();} for(int i=0;i<2;i++)pg[i].serial=8000+i; for(int i=0;i<2;i++){NvProg *p=[NvProg new];p->sh[0]=[NvShader new];p->sh[0]->fn=[l newFunctionWithName:@"v"];p->sh[1]=[NvShader new];p->sh[1]->stage=1;p->sh[1]->fn=[l newFunctionWithName:i?@"sample":@"red"];if(i){p->sh[1]->rf.nb=1;p->sh[1]->rf.b[0]=(nvn_rbind){.kind=NVN_RB_TEX,.reg=0,.dtt=2};p->sh[1]->ae=[p->sh[1]->fn newArgumentEncoderWithBufferIndex:0];}if(g_tnkeep<256)g_tkeep[g_tnkeep++]=p;serial_put(pg[i].serial,p);} }
/* Keyed one-stage programs bound as Unity binds them, pixel and vertex in two BindProgram calls with stage masks: the scans must combine them
   (prog_bind) as the replay does; the composite resolves through the shader map and the shader cache, as in play */
static prog_t g_kvs, g_kfs;
static void setup_keyed(void) { static int done; if(done) return; done=1; NSError *e=nil; id<MTLLibrary> l=[g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal; vertex float4 v(uint n[[vertex_id]]){float2 p[3]={float2(-1,-1),float2(3,-1),float2(-1,3)};return float4(p[n],0,1);}\nstruct A{texture2d<float> t[[id(0)]];}; fragment float4 sample(constant A&a[[buffer(0)]]){return a.t.read(uint2(0));}\n" options:nil error:&e]; if(!l){fprintf(stderr,"%s\n",e.localizedDescription.UTF8String);abort();}
    static const uint8_t kv[8]={0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88}, kf[8]={0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xf0,0x01};
    NvShader *vs=[NvShader new]; vs->fn=[l newFunctionWithName:@"v"];
    NvShader *fs=[NvShader new]; fs->stage=1; fs->fn=[l newFunctionWithName:@"sample"]; fs->rf.nb=1; fs->rf.b[0]=(nvn_rbind){.kind=NVN_RB_TEX,.reg=0,.dtt=2}; fs->ae=[fs->fn newArgumentEncoderWithBufferIndex:0];
    g_kvs=(prog_t){.nstage=1,.serial=8100}; memcpy(g_kvs.key[0],kv,8); g_kvs.kstage[0]=0;
    g_kfs=(prog_t){.nstage=1,.serial=8101}; memcpy(g_kfs.key[0],kf,8); g_kfs.kstage[0]=1;
    NvProg *pv=[NvProg new]; pv->sh[0]=vs; NvProg *pf=[NvProg new]; pf->sh[1]=fs; g_tkeep[g_tnkeep++]=pv; g_tkeep[g_tnkeep++]=pf; serial_put(8100,pv); serial_put(8101,pf);
    if(!g_shmap) g_shmap=[NSMutableDictionary dictionary]; g_shmap[@"1122334455667788"]=(id)@"vs"; g_shmap[@"99aabbccddeef001"]=(id)@"ps";
    if(!g_shcache) g_shcache=[NSMutableDictionary dictionary]; g_shcache[@"1122334455667788_b"]=vs; g_shcache[@"99aabbccddeef001_b"]=fs; }
static void bind_stages(chain *c, const prog_t *p, int stages) { p_bind_program b={p,stages}; emit(c,OP_BIND_PROGRAM,&b,sizeof b); }
static uint64_t run_case(int mode, int enabled, uint8_t px[256]) { tex_t a=tex(8),b=tex(8),q2=tex(8); int aid=view(&a,0), a1=view(&a,1); chain c=chain_new(); prog_t pg[2]={0}; setup_prog(pg); set_rt(&c,&a,NULL,0);clear_color(&c,0,0,0,0);ds_off(&c);bind_prog(&c,&pg[0]);blend(&c);draw_cmd(&c);set_rt(&c,&b,NULL,0);clear_color(&c,0,0,0,0);if(mode==1){uint64_t t=NVN_COUNTER_TYPE_SAMPLES_PASSED;emit(&c,OP_RESET_COUNTER,&t,sizeof t);}if(mode==2){bind_prog(&c,&pg[1]);bind_tex(&c,aid);}ds_off(&c);draw_cmd(&c);set_rt(&c,&a,&q2,0);if(mode==3)clear_color(&c,0,0,0,0);if(mode==6){setup_keyed();bind_stages(&c,&g_kfs,2);bind_stages(&c,&g_kvs,1);}else bind_prog(&c,&pg[1]);bind_tex(&c,mode==5||mode==6?aid:a1);draw_cmd(&c);emit(&c,OP_END,NULL,0);state_reset();memset(&R,0,sizeof R);vis_clear();g_vis_on=g_vis_counting=0;if(!enabled)setenv("DM_NVN_DEFER","0",1);else setenv("DM_NVN_DEFER","1",1);uint64_t start=g_stat_pass;mtl_sub_begin();uint64_t hh=(uint64_t)c.p;mtl_sub_index(&hh,1);mtl_exec(c.p);readback(&a,px);return g_stat_pass-start; }
static uint64_t run_multi(int enabled, uint8_t px[256]) { tex_t a=tex(8),b=tex(8),mid=tex(8); chain c=chain_new(); static prog_t pg[2]; memset(pg,0,sizeof pg);   /* Static: the program cache is keyed by prog_t address, and on the stack it would share an address with run_case's pg */ setup_prog(pg); set_rt(&c,&a,NULL,0);clear_color(&c,0,0,0,0);ds_off(&c);bind_prog(&c,&pg[0]);blend(&c);draw_cmd(&c);set_rt(&c,&mid,NULL,0);ds_off(&c);draw_cmd(&c);set_rt(&c,&b,NULL,0);clear_color(&c,0,0,0,0);draw_cmd(&c);set_rt(&c,&a,&b,0);bind_prog(&c,&pg[0]);draw_cmd(&c);emit(&c,OP_END,NULL,0);state_reset();memset(&R,0,sizeof R);vis_clear();g_vis_on=g_vis_counting=0;setenv("DM_NVN_DEFER",enabled?"1":"0",1);uint64_t start=g_stat_pass;mtl_sub_begin();uint64_t hh=(uint64_t)c.p;mtl_sub_index(&hh,1);mtl_exec(c.p);readback(&a,px);return g_stat_pass-start; }
static uint64_t run_chain_id(int enabled, uint8_t px[256]) {   /* Chained positive case: A is attachment 0 in all three passes - P1 draws A; P2's pass (A, D) is P1's Q, P2 draws A and is deferred as a whole into Q2 (A, D) */
    tex_t a=tex(8),d=tex(8),mid=tex(8); chain c=chain_new(); static prog_t pg[2]; memset(pg,0,sizeof pg); setup_prog(pg);
    set_rt(&c,&a,NULL,0);clear_color(&c,0,0,0,0);ds_off(&c);bind_prog(&c,&pg[0]);blend(&c);draw_cmd(&c);
    set_rt(&c,&mid,NULL,0);ds_off(&c);draw_cmd(&c);
    set_rt(&c,&a,&d,0);clear_color(&c,1,0,0,0);draw_cmd(&c);
    set_rt(&c,&mid,NULL,0);draw_cmd(&c);
    set_rt(&c,&a,&d,0);bind_prog(&c,&pg[0]);draw_cmd(&c);emit(&c,OP_END,NULL,0);
    state_reset();memset(&R,0,sizeof R);vis_clear();g_vis_on=g_vis_counting=0;setenv("DM_NVN_DEFER",enabled?"1":"0",1);
    uint64_t start=g_stat_pass;mtl_sub_begin();uint64_t hh=(uint64_t)c.p;mtl_sub_index(&hh,1);mtl_exec(c.p);readback(&a,px);return g_stat_pass-start; }
static uint64_t run_chain(int enabled, uint8_t px[256]) {   /* Chained: P1 draws A; P2's pass (D, A) is exactly P1's Q, P2 itself draws D and is deferred as a whole into Q2 (A, D) - A's index differs between the two passes (1 → 0), and if the mapping is composed wrongly A gets drawn onto D */
    tex_t a=tex(8),d=tex(8),mid=tex(8); chain c=chain_new(); static prog_t pg[2]; memset(pg,0,sizeof pg); setup_prog(pg);
    set_rt(&c,&a,NULL,0);clear_color(&c,0,0,0,0);ds_off(&c);bind_prog(&c,&pg[0]);blend(&c);draw_cmd(&c);
    set_rt(&c,&mid,NULL,0);ds_off(&c);draw_cmd(&c);
    set_rt(&c,&d,&a,0);clear_color(&c,0,0,0,0);draw_cmd(&c);
    set_rt(&c,&mid,NULL,0);draw_cmd(&c);
    set_rt(&c,&a,&d,0);bind_prog(&c,&pg[0]);draw_cmd(&c);emit(&c,OP_END,NULL,0);
    state_reset();memset(&R,0,sizeof R);vis_clear();g_vis_on=g_vis_counting=0;setenv("DM_NVN_DEFER",enabled?"1":"0",1);
    uint64_t start=g_stat_pass;mtl_sub_begin();uint64_t hh=(uint64_t)c.p;mtl_sub_index(&hh,1);mtl_exec(c.p);readback(&a,px);return g_stat_pass-start; }
int main(void){@autoreleasepool{setvbuf(stdout,NULL,_IONBF,0);setenv("DM_NVN_TBDR","1",1);mtl_init();uint8_t p[256];uint8_t off[256];uint64_t n0=run_case(0,0,off);uint64_t d0=g_defer_n;uint64_t n1=run_case(0,1,p);uint64_t d1=g_defer_n;EXPECT("positive case: deferral count",1,d1-d0);EXPECT("positive case: one pass fewer when on",1,n0-n1);EXPECT("positive case: pixel not black",1,p[0]>0);EXPECT("positive case: on/off byte-identical",0,(uint64_t)memcmp(p,off,256));
uint64_t m0=run_multi(0,off);uint64_t md0=g_defer_n;uint64_t m1=run_multi(1,p);EXPECT("same Q, two groups: deferral count (B has a different index in Q, only A holds)",1,g_defer_n-md0);EXPECT("same Q, two groups: one pass fewer when on",1,m0-m1);EXPECT("same Q, two groups: on/off byte-identical",0,(uint64_t)memcmp(p,off,256));
uint64_t k0=run_chain(0,off);uint64_t kd0=g_defer_n;uint64_t k1=run_chain(1,p);EXPECT("chained, different index: not deferred",0,g_defer_n-kd0);EXPECT("chained, different index: pass count unchanged when on",0,k0-k1);EXPECT("chained: on/off byte-identical",0,(uint64_t)memcmp(p,off,256));
uint64_t j0=run_chain_id(0,off);uint64_t jd0=g_defer_n;uint64_t j1=run_chain_id(1,p);EXPECT("chained identity: two groups hold",2,g_defer_n-jd0);EXPECT("chained identity: two passes fewer when on",2,j0-j1);EXPECT("chained identity: on/off byte-identical",0,(uint64_t)memcmp(p,off,256));
for(int m=1;m<=6;m++){run_case(m,0,off);uint64_t before=g_defer_n;run_case(m,1,p);EXPECT(m==6?"pixel then vertex bound with stage masks, the pixel shader samples P: not deferred":m==2||m==3||m==5?"negative case: not deferred":"another positive case: still deferred",m==2||m==3||m==5||m==6?0:1,g_defer_n-before);EXPECT("on/off byte-identical",0,(uint64_t)memcmp(p,off,256));}{NSString *bp=[NSTemporaryDirectory() stringByAppendingPathComponent:@"t_bf_want.tsv"];unlink(bp.fileSystemRepresentation);setenv("DM_NVN_BF_WANT",bp.fileSystemRepresentation,1);bf_want_note("0123456789abcdef_b");bf_want_note("0123456789abcdef_b");bf_want_note("0123456789abcdeg_b");bf_want_note("0123456789abcdef0_b");bf_want_note("fedcba9876543210_b");NSString *got=[NSString stringWithContentsOfFile:bp encoding:NSUTF8StringEncoding error:nil];EXPECT("bf want list: library-suffixed keys recorded once as 16 hex digits, malformed ones skipped",1,(uint64_t)[got isEqualToString:@"0123456789abcdef\nfedcba9876543210\n"]);unsetenv("DM_NVN_BF_WANT");unlink(bp.fileSystemRepresentation);}
